UPDATE "conversation_task_agent_execution"
SET "modifier_id" = #{userId}, "status" = #{status},
    "provider_request_id" = COALESCE(#{providerRequestId}, "provider_request_id"),
    "error_code" = COALESCE(#{errorCode}, "error_code"),
    "error_message" = COALESCE(#{errorMessage}, "error_message"), "end_time" = #{endTime}
WHERE "id" = #{executionId} AND "creator_id" = #{userId}
